<script setup>import {ref} from 'vue';import {Head,Link,router} from '@inertiajs/vue3';import AppLayout from '@/Layouts/AppLayout.vue';import Button from '@/Components/UI/Button.vue';import Icon from '@/Components/UI/Icon.vue';import HrNav from '../Partials/HrNav.vue';import {usePermissions} from '@/composables/usePermissions';defineOptions({layout:AppLayout});const props=defineProps({report:Object,filters:Object});const {can}=usePermissions();const from=ref(props.filters.from),to=ref(props.filters.to);const apply=()=>router.get('/administration/reports',{from:from.value,to:to.value},{preserveState:true,replace:true});const duration=m=>`${Math.floor(m/60)} h ${m%60} min`;</script><template><Head title="Rapports RH"/><div class="space-y-5"><HrNav/><header class="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p class="text-xs font-bold uppercase tracking-[.15em] text-emerald-600">Pilotage administratif</p><h1 class="mt-1 font-heading text-3xl font-bold text-slate-800 dark:text-white">Rapports RH</h1><p class="mt-2 text-sm text-slate-500">Indicateurs factuels des dossiers, contrats, présences, congés et plannings.</p></div><div class="flex gap-2"><Button v-if="can('hr_reports.print')" :as="Link" :href="`/administration/reports/print?from=${from}&to=${to}`" size="rg" variant="white-outline"><Icon name="printer"/><span class="ms-2">Imprimer</span></Button><Button v-if="can('hr_reports.export')" as="a" :href="`/administration/reports/export?from=${from}&to=${to}`" size="rg"><Icon name="download"/><span class="ms-2">Exporter Excel</span></Button></div></header><form class="flex flex-wrap gap-3 rounded-xl border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-900 dark:bg-gray-950" @submit.prevent="apply"><input v-model="from" type="date" class="h-10 rounded-lg border border-gray-200 px-3 text-sm dark:border-gray-800 dark:bg-gray-950"><input v-model="to" type="date" class="h-10 rounded-lg border border-gray-200 px-3 text-sm dark:border-gray-800 dark:bg-gray-950"><Button size="rg">Actualiser</Button></form><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><div v-for="item in [{label:'Employés actifs',value:report.summary.active_employees},{label:'Contrats en cours',value:report.summary.current_contracts},{label:'Sessions de présence',value:report.summary.attendance_sessions},{label:'Temps constaté',value:duration(report.summary.attendance_minutes)},{label:'Congés acceptés',value:report.summary.approved_leave},{label:'Congés en attente',value:report.summary.pending_leave},{label:'Créneaux planifiés',value:report.summary.planning_shifts}]" :key="item.label" class="rounded-xl border border-gray-200 bg-white p-5 shadow-sm dark:border-gray-900 dark:bg-gray-950"><p class="text-xs font-bold uppercase tracking-wide text-slate-400">{{item.label}}</p><p class="mt-2 text-2xl font-black text-slate-800 dark:text-white">{{item.value}}</p></div></section><section class="grid gap-5 lg:grid-cols-2"><article class="rounded-xl border border-gray-200 bg-white p-5 shadow-sm dark:border-gray-900 dark:bg-gray-950"><h2 class="font-bold text-slate-800 dark:text-white">Effectif actif par département</h2><div class="mt-4 space-y-3"><div v-for="item in report.by_department" :key="item.uuid" class="flex items-center justify-between border-b border-gray-100 pb-3 text-sm last:border-0"><span>{{item.label}}</span><strong>{{item.count}}</strong></div></div></article><article class="rounded-xl border border-gray-200 bg-white p-5 shadow-sm dark:border-gray-900 dark:bg-gray-950"><h2 class="font-bold text-slate-800 dark:text-white">Congés sur la période</h2><div class="mt-4 space-y-3"><div v-for="item in report.leave_statuses" :key="item.status" class="flex items-center justify-between border-b border-gray-100 pb-3 text-sm last:border-0"><span>{{item.label}}</span><strong>{{item.count}}</strong></div></div></article></section><div class="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800"><strong>Paie non activée.</strong> Aucun salaire, CNAPS ou IRSA n’est calculé : les formules transmises doivent être validées officiellement avant toute automatisation.</div></div></template>
